Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Module RlDec.
Import Ltac2.Ltac2 Ltac2.Constr.

Ltac2 rl_step () : constr := constr:(@OSSVerify.Proofs.leptonica.bilateral_fuzzer.lib.K5.Lib.StepFast.sf_evt_step).

Ltac2 rec rl_fix (f0 : constr) (pcs : constr list) (c : constr) : constr :=
  match Constr.Unsafe.kind c with
  | Constr.Unsafe.App f args =>
    let args := Array.of_list (List.map (rl_fix f0 pcs) (Array.to_list args)) in
    let hit :=
      if Constr.equal f f0 then
        if Int.equal (Array.length args) 18 then List.exist (fun q => Constr.equal q (Array.get args 4)) pcs else false
      else false in
    if hit then
      let i := Array.get args 10 in
      let sz := Array.get args 11 in
      Array.set args 15 constr:(@eq_refl (option (instr * Z)) (@Some (instr * Z) (@pair instr Z $i $sz)));
      Constr.Unsafe.make (Constr.Unsafe.App f args)
    else Constr.Unsafe.make (Constr.Unsafe.App (rl_fix f0 pcs f) args)
  | _ => Constr.Unsafe.map (rl_fix f0 pcs) c
  end.

Ltac2 run1 (tab : string) (secs : string list) (s : string) (pcs : constr list) : unit :=
  KReplay.kr_revert ();
  let ph := Ref.ref [] in
  let c := KReplay.decode_ph (Some ph) tab (KReplay.kr_secs secs) s in
  let f0 := rl_step () in
  Std.exact_no_check (rl_fix f0 pcs c);
  List.iter (fun (e, b) => Control.new_goal e; Control.enter (fun () => Std.exact_no_check (rl_fix f0 pcs b))) (Ref.get ph).
End RlDec.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

